import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import api from "../api/axios";
import { useSocket } from "../context/SocketContext";

export default function AgentDashboard() {
  const { socket } = useSocket();
  const [available, setAvailable] = useState([]);
  const [myOrders, setMyOrders] = useState([]);

  const loadMine = () => api.get("/orders/mine").then(({ data }) => setMyOrders(data));

  useEffect(() => {
    loadMine();
  }, []);

  useEffect(() => {
    if (!socket) return;
    const onAvailable = (order) => setAvailable((prev) => [order, ...prev]);
    socket.on("order:available_for_pickup", onAvailable);
    return () => socket.off("order:available_for_pickup", onAvailable);
  }, [socket]);

  const accept = async (orderId) => {
    await api.put(`/orders/${orderId}/assign`);
    setAvailable((prev) => prev.filter((o) => o._id !== orderId));
    loadMine();
  };

  const deliver = async (orderId) => {
    await api.put(`/orders/${orderId}/deliver`);
    loadMine();
  };

  const active = myOrders.filter((o) => o.status === "out_for_delivery");
  const past = myOrders.filter((o) => o.status === "delivered");

  return (
    <div className="page">
      <div className="eyebrow">Delivery agent</div>
      <h1>Available pickups</h1>
      <hr className="route-rule" style={{ margin: "20px 0 28px" }} />

      {available.length === 0 && (
        <div className="empty-state">No pickups broadcasted yet. You'll be notified the instant a restaurant marks an order ready.</div>
      )}
      <div className="grid" style={{ marginBottom: 32 }}>
        {available.map((o) => (
          <div key={o._id} className="card">
            <strong>#{o._id.slice(-6).toUpperCase()}</strong>
            <p style={{ fontSize: 14, color: "var(--paper-dim)", margin: "8px 0" }}>
              {o.items.length} item(s) · ₹{o.totalAmount}
            </p>
            <button className="btn btn-primary btn-sm btn-block" onClick={() => accept(o._id)}>
              Accept delivery
            </button>
          </div>
        ))}
      </div>

      {active.length > 0 && (
        <>
          <h3 style={{ marginBottom: 14 }}>Your active delivery</h3>
          <div className="grid" style={{ marginBottom: 32 }}>
            {active.map((o) => (
              <div key={o._id} className="card">
                <strong>#{o._id.slice(-6).toUpperCase()}</strong>
                <span className="badge badge-live" style={{ marginLeft: 8 }}>out for delivery</span>
                <p style={{ fontSize: 14, color: "var(--paper-dim)", margin: "8px 0" }}>₹{o.totalAmount}</p>
                <Link to={`/orders/${o._id}`} className="btn btn-ghost btn-sm" style={{ marginRight: 8 }}>
                  Open live map
                </Link>
                <button className="btn btn-primary btn-sm" onClick={() => deliver(o._id)}>
                  Mark delivered
                </button>
              </div>
            ))}
          </div>
        </>
      )}

      {past.length > 0 && (
        <>
          <h3 style={{ marginBottom: 14 }}>Completed</h3>
          <div className="grid">
            {past.map((o) => (
              <div key={o._id} className="card">
                <strong>#{o._id.slice(-6).toUpperCase()}</strong>
                <span className="badge badge-done" style={{ marginLeft: 8 }}>delivered</span>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}
